insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id from jsonb_to_recordset($bank$[{"id":"che-ek-173","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Electrolysis of molten sodium chloride yields, as the electrode products,","options":["sodium metal at the cathode and chlorine gas at the anode","hydrogen at the cathode and oxygen at the anode","chlorine at both electrodes","solid NaCl crystals on the anode"],"answer_index":0,"explanation":"In the melt the only ions are Na$^+$ and Cl$^-$, so Na and Cl$_2$ are discharged.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday"},{"id":"che-ek-174","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"When aqueous CuSO$_4$ is electrolysed with copper electrodes, the anode reaction is","options":["dissolution of copper metal as Cu$^{2+}$","evolution of oxygen from water","deposition of solid sulphur","reduction of Cu$^{2+}$ to Cu"],"answer_index":0,"explanation":"A copper anode is oxidised in preference to water or sulphate, so the anode loses mass while copper plates at the cathode.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday"},{"id":"che-ek-175","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Preferential discharge at an electrode is decided by","options":["the ion that is most easily reduced (or oxidised) under the prevailing conditions","the ion present in the largest catalogue mass only","the colour of the electrolyte","the cell constant of the vessel"],"answer_index":0,"explanation":"The couple with the more favourable discharge potential (including overvoltage and concentration) is liberated first.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday"},{"id":"che-ek-176","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The quantity of electricity $Q$ that flows in time $t$ at a steady current $I$ is","options":["$Q = It$","$Q = I/t$","$Q = t/I$","$Q = I + t$"],"answer_index":0,"explanation":"Current is charge per unit time, so charge is the product $It$ (amperes × seconds = coulombs).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday"},{"id":"che-ek-177","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Electrolysis of acidified water with inert electrodes liberates","options":["hydrogen at the cathode and oxygen at the anode, in a 2 : 1 volume ratio","oxygen at the cathode and hydrogen at the anode","only hydrogen, because oxygen stays dissolved","chlorine and sodium"],"answer_index":0,"explanation":"2 H$_2$O → 2 H$_2$ + O$_2$. Two moles of hydrogen appear for each mole of oxygen.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday"},{"id":"che-ek-178","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"During electrolysis the cathode is still defined as the electrode at which","options":["reduction occurs","oxidation occurs","the external battery is connected to earth","no ion can be discharged"],"answer_index":0,"explanation":"The cathode/anode labels follow the chemistry (reduction/oxidation), not the galvanic sign convention.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday"},{"id":"che-ek-179","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Electrochemical equivalent $Z$ of a substance equals","options":["molar mass divided by $nF$","molar mass multiplied by $nF$","$nF$ alone","cell constant divided by $\\kappa$"],"answer_index":0,"explanation":"$m = ZQ$ with $Z = M/(nF)$, so $Z$ is the mass liberated by one coulomb.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday"},{"id":"che-ek-180","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"To deposit one mole of aluminium from Al$^{3+}$ one must pass a charge of","options":["$3F$","$1F$","$2F$","$F/3$"],"answer_index":0,"explanation":"Each Al$^{3+}$ ion consumes three electrons, so 1 mol Al requires $3 \\times 96500\\ \\mathrm{C}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electrolysis-faraday"},{"id":"che-ek-181","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A 1.0 A current sent for 965 s through aqueous AgNO$_3$ deposits silver (Ag = 108) amounting to","options":["$1.08\\ \\mathrm{g}$","$10.8\\ \\mathrm{g}$","$0.108\\ \\mathrm{g}$","$108\\ \\mathrm{g}$"],"answer_index":0,"explanation":"$m = (108/96500) \\times 1.0 \\times 965 = 1.08\\ \\mathrm{g}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electrolysis-faraday"},{"id":"che-ek-182","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"How many coulombs are required to plate 0.50 mol of copper from Cu$^{2+}$?","options":["$96500\\ \\mathrm{C}$","$48250\\ \\mathrm{C}$","$193000\\ \\mathrm{C}$","$0.50\\ \\mathrm{C}$"],"answer_index":0,"explanation":"Each mole of Cu$^{2+}$ needs 2 mol electrons, so 0.50 mol needs $1.0\\,F = 96500\\ \\mathrm{C}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electrolysis-faraday"},{"id":"che-ek-183","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A 2.0 A current flows for 965 s through acidified water. The STP volume of H$_2$ evolved is nearest","options":["$0.224\\ \\mathrm{L}$","$22.4\\ \\mathrm{L}$","$0.112\\ \\mathrm{L}$","$2.24\\ \\mathrm{L}$"],"answer_index":0,"explanation":"$Q = 1930\\ \\mathrm{C} = 0.020\\ \\mathrm{mol\\ e^-}$; $2\\,e^- \\to 1\\ \\mathrm{H_2}$, so $0.010\\ \\mathrm{mol} = 0.224\\ \\mathrm{L}$ at STP.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electrolysis-faraday"},{"id":"che-ek-184","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"To deposit 0.216 g of Ag (Ag = 108) from AgNO$_3$ at 0.50 A, the time required is","options":["386 s","193 s","965 s","1930 s"],"answer_index":0,"explanation":"$Q = m \\times F / M = 0.216 \\times 96500 / 108 = 193\\ \\mathrm{C}$; $t = Q/I = 193/0.50 = 386\\ \\mathrm{s}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electrolysis-faraday"},{"id":"che-ek-185","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The same charge that deposits 1.08 g of silver will deposit, from Cu$^{2+}$ (Cu = 63.5), a copper mass of","options":["$0.318\\ \\mathrm{g}$","$1.08\\ \\mathrm{g}$","$0.635\\ \\mathrm{g}$","$2.16\\ \\mathrm{g}$"],"answer_index":0,"explanation":"Equivalents: $E(\\mathrm{Ag}) = 108$, $E(\\mathrm{Cu}) = 31.75$. $m_{\\mathrm{Cu}} = 1.08 \\times 31.75/108 = 0.318\\ \\mathrm{g}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electrolysis-faraday"},{"id":"che-ek-186","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"If 0.635 g of copper is plated from CuSO$_4$ in 1930 s, the steady current used was","options":["$1.0\\ \\mathrm{A}$","$0.50\\ \\mathrm{A}$","$2.0\\ \\mathrm{A}$","$0.10\\ \\mathrm{A}$"],"answer_index":0,"explanation":"$Q = (0.635 \\times 2 \\times 96500)/63.5 = 1930\\ \\mathrm{C}$; $I = Q/t = 1930/1930 = 1.0\\ \\mathrm{A}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electrolysis-faraday"},{"id":"che-ek-187","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A current of 2.0 A is passed for 30 min through molten Al$_2$O$_3$ (Al = 27). The mass of aluminium liberated is","options":["$0.336\\ \\mathrm{g}$","$1.008\\ \\mathrm{g}$","$0.112\\ \\mathrm{g}$","$9.00\\ \\mathrm{g}$"],"answer_index":0,"explanation":"$Q = 2.0 \\times 1800 = 3600\\ \\mathrm{C}$. $m = (27 \\times 3600)/(3 \\times 96500) \\approx 0.336\\ \\mathrm{g}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"electrolysis-faraday"},{"id":"che-ek-188","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The same current flows for the same time through AgNO$_3$ and then, separately, through AuCl$_3$ (Au = 197). If 1.08 g Ag is deposited, the gold deposited is nearest","options":["$0.657\\ \\mathrm{g}$","$1.97\\ \\mathrm{g}$","$0.328\\ \\mathrm{g}$","$3.00\\ \\mathrm{g}$"],"answer_index":0,"explanation":"Equal charge means equal equivalents: $m_{\\mathrm{Au}}/m_{\\mathrm{Ag}} = (197/3)/108$, so $m_{\\mathrm{Au}} = 1.08 \\times 197/(3 \\times 108) = 0.657\\ \\mathrm{g}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"electrolysis-faraday"},{"id":"che-ek-189","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A primary electrochemical cell is one that","options":["cannot be recharged by reversing the current","is recharged simply by plugging it into the mains","has no electrode at all","works only as an electrolytic cell"],"answer_index":0,"explanation":"Once the reductant and oxidant of a dry cell or button cell are spent, the cell is discarded.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"batteries-corrosion"},{"id":"che-ek-190","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A secondary cell differs from a primary cell in that it","options":["can be recharged because the cell reaction is reversible","never involves a redox change","has $E = 0$ at all times","must be discarded after a single use"],"answer_index":0,"explanation":"Lead–acid and Ni–Cd cells are secondary batteries: charging drives the discharge reaction backwards.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"batteries-corrosion"},{"id":"che-ek-191","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The common dry cell (Leclanché) uses a zinc cup as the anode and, as the cathode depolariser,","options":["manganese dioxide packed around a carbon rod","lead dioxide on a lead grid","porous platinum and hydrogen gas","solid sodium chloride only"],"answer_index":0,"explanation":"Zn is oxidised; MnO$_2$ is reduced at the carbon collector in the NH$_4$Cl / ZnCl$_2$ paste.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"batteries-corrosion"},{"id":"che-ek-192","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A hydrogen–oxygen fuel cell is designed so that the reactants are","options":["fed continuously, and the cell can run as long as fuel and oxidant are supplied","sealed once and for all inside a closed can","generated only by charging overnight","the same as those of a lead storage battery"],"answer_index":0,"explanation":"A fuel cell is a galvanic cell with continuous feeds; it is not a store of a finite charge like a battery.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"batteries-corrosion"}]$bank$::jsonb) as t(id text, chapter_id text, subject_id text, stem text, options jsonb, answer_index int, explanation text, images jsonb, source jsonb, difficulty text, concept_id text) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
insert into question_pyq_meta (question_id, appear_count, years, exams, verified) select question_id, appear_count, years, exams, verified from jsonb_to_recordset($meta$[{"question_id":"che-ek-173","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-174","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-175","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-176","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-177","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-178","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-179","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-180","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-181","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-182","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-183","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-184","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-185","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-186","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-187","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-188","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-189","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-190","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-191","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-192","appear_count":0,"years":[],"exams":[],"verified":false}]$meta$::jsonb) as t(question_id text, appear_count int, years int[], exams text[], verified boolean) on conflict (question_id) do update set appear_count = excluded.appear_count, years = excluded.years, exams = excluded.exams, verified = excluded.verified;
